//! Editing a Piff's content from the desktop app.
//!
//! The webview edits the whole text of `PIFF.md`, but it never writes the
//! file itself. Every save goes through [`Piff::write_content`], so the
//! children section is regenerated by `nodir-core`'s writer and the bytes
//! outside the markers are exactly what the user typed.
//!
//! A save carries the file's text as the editor last saw it. If the file on
//! disk has changed since (an external editor wrote it), nothing is written
//! and the caller gets the new text back to merge or ask the user about.

use nodir_core::{section, Piff, SyncMode};
use serde::Serialize;

use crate::browse::Result;
use crate::render;

/// A Piff's content as the editor needs it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PiffDoc {
    /// Whether `PIFF.md` exists. A Piff without one is empty, and the editor
    /// starts with an empty document; the file is created on the first save.
    pub exists: bool,
    /// The file's text exactly as stored, or `""` if it does not exist.
    pub text: String,
    /// Where the children section sits in `text`, in UTF-16 code units (the
    /// webview's string offsets), if the text has one.
    pub section: Option<Span>,
    /// The children section rendered to sanitized HTML. When `text` has no
    /// section, this is the section a save would add.
    pub children_html: String,
    /// The text's line ending, `"\n"` or `"\r\n"`, which the editor uses for
    /// new lines so a CRLF file stays CRLF.
    pub line_ending: &'static str,
}

/// A range in UTF-16 code units.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct Span {
    pub from: usize,
    pub to: usize,
}

/// The outcome of a save.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum SaveResult {
    /// The text was written; `doc` is the file as it now is on disk, with a
    /// regenerated children section.
    Saved { doc: PiffDoc },
    /// The file changed on disk since the editor last saw it, so nothing was
    /// written. `doc` is what is on disk now.
    Conflict { doc: PiffDoc },
}

/// Reads a Piff's content for the editor. Writes nothing.
pub fn read(piff: &Piff) -> Result<PiffDoc> {
    let disk = piff.read().map_err(|e| e.to_string())?;
    let exists = disk.is_some();
    let text = disk.unwrap_or_default();
    let range = section::find(&text);
    let children_md = match &range {
        Some(r) => text[r.clone()].to_string(),
        // What a save would add: the section of the content rendered in
        // memory.
        None => {
            let rendered = piff.render().map_err(|e| e.to_string())?;
            section::split(&rendered)
                .section
                .unwrap_or_default()
                .to_string()
        }
    };
    Ok(PiffDoc {
        exists,
        section: range.map(|r| Span {
            from: utf16_len(&text[..r.start]),
            to: utf16_len(&text[..r.end]),
        }),
        children_html: render::markdown(&children_md),
        line_ending: section::line_ending(&text),
        text,
    })
}

/// Writes `text` as the Piff's content, unless the file on disk is no longer
/// `expected` (`None`: the file must not exist). Creates `PIFF.md` if needed.
pub fn save(piff: &Piff, text: &str, expected: Option<&str>) -> Result<SaveResult> {
    let disk = piff.read().map_err(|e| e.to_string())?;
    if disk.as_deref() != expected {
        return Ok(SaveResult::Conflict { doc: read(piff)? });
    }
    piff.write_content(text).map_err(|e| e.to_string())?;
    Ok(SaveResult::Saved { doc: read(piff)? })
}

/// Makes sure `PIFF.md` exists, so an external editor has a file to open.
/// The user asked for it, so this is one of the few places NoDir creates a
/// content file without the user typing into it.
pub fn ensure_content_file(piff: &Piff) -> Result<()> {
    piff.sync(SyncMode::CreateIfMissing)
        .map(|_| ())
        .map_err(|e| e.to_string())
}

fn utf16_len(s: &str) -> usize {
    s.chars().map(char::len_utf16).sum()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    fn piff_with(content: Option<&str>) -> (tempfile::TempDir, Piff) {
        let tmp = tempfile::tempdir().unwrap();
        fs::create_dir(tmp.path().join("child")).unwrap();
        fs::write(tmp.path().join("notes.md"), "x").unwrap();
        if let Some(content) = content {
            fs::write(tmp.path().join("PIFF.md"), content).unwrap();
        }
        let piff = Piff::open(tmp.path()).unwrap();
        (tmp, piff)
    }

    fn on_disk(piff: &Piff) -> Option<String> {
        fs::read_to_string(piff.content_path()).ok()
    }

    #[test]
    fn reading_an_empty_piff_writes_nothing() {
        let (_tmp, piff) = piff_with(None);
        let doc = read(&piff).unwrap();
        assert!(!doc.exists);
        assert_eq!(doc.text, "");
        assert_eq!(doc.section, None);
        assert!(doc.children_html.contains("child/PIFF.md"));
        assert!(on_disk(&piff).is_none());
    }

    #[test]
    fn first_save_creates_the_file_with_a_section() {
        let (_tmp, piff) = piff_with(None);
        let SaveResult::Saved { doc } = save(&piff, "# Hi\n", None).unwrap() else {
            panic!("expected a save");
        };
        let disk = on_disk(&piff).unwrap();
        assert_eq!(doc.text, disk);
        assert!(disk.starts_with("# Hi\n\n<!-- nodir:children:start -->"));
        assert!(doc.exists);
    }

    #[test]
    fn section_offsets_are_utf16() {
        let (_tmp, piff) = piff_with(Some("# Ünïcødé 🙂\n"));
        piff.sync(SyncMode::ExistingOnly).unwrap();
        let doc = read(&piff).unwrap();
        let span = doc.section.unwrap();
        let utf16: Vec<u16> = doc.text.encode_utf16().collect();
        let section = String::from_utf16(&utf16[span.from..span.to]).unwrap();
        assert!(section.starts_with(section::START_MARKER));
        assert!(section.ends_with(section::END_MARKER));
    }

    #[test]
    fn save_keeps_user_bytes_and_regenerates_the_section() {
        let user = "# Title\r\n\r\nSome *text*\r\n\r\n";
        let stale = "<!-- nodir:children:start -->\r\n- [gone](gone)\r\n<!-- nodir:children:end -->\r\nafter";
        let (_tmp, piff) = piff_with(Some(&format!("{user}{stale}")));
        let expected = on_disk(&piff);
        let edited = format!("{user}More\r\n\r\n{stale}");
        let SaveResult::Saved { doc } = save(&piff, &edited, expected.as_deref()).unwrap() else {
            panic!("expected a save");
        };
        let disk = on_disk(&piff).unwrap();
        assert_eq!(doc.text, disk);
        assert_eq!(doc.line_ending, "\r\n");
        assert!(disk.starts_with(&format!("{user}More\r\n\r\n")), "{disk:?}");
        assert!(
            disk.ends_with("<!-- nodir:children:end -->\r\nafter"),
            "{disk:?}"
        );
        assert!(disk.contains("- [child/](child/PIFF.md)\r\n"), "{disk:?}");
        assert!(!disk.contains("gone"));
    }

    #[test]
    fn save_refuses_when_the_file_changed() {
        let (_tmp, piff) = piff_with(Some("old\n"));
        fs::write(piff.content_path(), "changed elsewhere\n").unwrap();
        let result = save(&piff, "mine\n", Some("old\n")).unwrap();
        let SaveResult::Conflict { doc } = result else {
            panic!("expected a conflict");
        };
        assert_eq!(doc.text, "changed elsewhere\n");
        assert_eq!(on_disk(&piff).unwrap(), "changed elsewhere\n");
    }

    #[test]
    fn save_refuses_to_recreate_or_overwrite_unexpectedly() {
        // The editor thought the file was missing, but it has appeared.
        let (_tmp, piff) = piff_with(Some("appeared\n"));
        assert!(matches!(
            save(&piff, "mine", None).unwrap(),
            SaveResult::Conflict { .. }
        ));
        // The editor thought the file existed, but it was deleted.
        let (_tmp, piff) = piff_with(None);
        assert!(matches!(
            save(&piff, "mine", Some("old")).unwrap(),
            SaveResult::Conflict { .. }
        ));
        assert!(on_disk(&piff).is_none());
    }

    #[test]
    fn ensure_content_file_creates_only_when_missing() {
        let (_tmp, piff) = piff_with(None);
        ensure_content_file(&piff).unwrap();
        assert!(on_disk(&piff).unwrap().contains("child/PIFF.md"));
        let (_tmp, piff) = piff_with(Some("keep me\n"));
        ensure_content_file(&piff).unwrap();
        assert!(on_disk(&piff).unwrap().starts_with("keep me\n\n"));
    }
}
